  // LG3: drain the freshly reset, just-halted hart into a baseline the
  // liveness gate compares restores against. The probe carries the incoming
  // state's flags/vlenb so drain_with_passthrough reads exactly the blocks
  // the gate will compare (it is flag-driven); every probe field it does not
  // re-read stays zero, matching what an absent block compares against.
  auto capture_reset_baseline(
    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
                          PLATFORM::dmi_data_width>& bus,
    const hybrid_state_v1& input) -> hybrid_state_v1
  {
    hybrid::StateDrain drain(bus, v_scratch_gpa(),
                             hybrid::andes_caps_from_config());
    drain.set_gpr_block_store(true);
    drain.set_fpr_block_store(true);
    drain.set_csr_sweep(true);
    // At reset mstatus.FS/VS are Off, so the capture's fsd/vse8 sweeps (and
    // the FPR/V CSR abstract reads) would raise illegal instruction
    // (cmderr=3). Halt and enable them first, exactly like resume() does
    // before its FPR/V writes. Safe to clobber: mstatus is never re-read by
    // a drain nor gated by the baseline, and resume() rewrites it whenever
    // the FP/V flags are set -- the only case this branch runs.
    if (input.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
      using RD = hybrid::ResumeDriver;
      bus.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
      bus.write(RD::kDmcontrol,
                RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
      hybrid::poll_until_set(bus, RD::kDmstatus, RD::kDmstatusAllhalted,
                             "reset-baseline capture halt");
      const uint64_t mstatus = hybrid::read_register_64(
        bus, hybrid::regno_csr(RD::kCsrMstatus), "reset-baseline mstatus");
      uint64_t enable = mstatus;
      if ((input.flags & HYBRID_FLAG_FP)
          && (enable & RD::kMstatusFsMask) == 0)
        enable |= RD::kMstatusFsInitial;
      if ((input.flags & HYBRID_FLAG_V)
          && (enable & RD::kMstatusVsMask) == 0)
        enable |= RD::kMstatusVsInitial;
      if (enable != mstatus)
        hybrid::write_register_abstract(
          bus, hybrid::regno_csr(RD::kCsrMstatus), enable);
    }
    hybrid_state_v1 probe{};
    probe.magic = HYBRID_STATE_MAGIC;
    probe.version = HYBRID_STATE_VERSION;
    probe.flags = input.flags;
    probe.vlenb = input.vlenb;
    auto baseline = drain.drain_with_passthrough(probe);
    lift_scratch_blocks(baseline, /*csr_swept=*/true);
    return baseline;
  }

  // Lift the scratch-page transports into `state` (dual of the resume
  // staging): the V dump sweep bytes back into state.vreg[] -- so the drained
  // state carries vsim's actual V values, not QEMU 1's stale snapshot -- and
  // the drain sd/fsd block-store sweeps (x1..x30 / f0..f31) into the GPR/FPR
  // slots. Gated on the SAME fits conditions StateDrain used to pick
  // sweep-vs-abstract: when the V page is full it read the registers via
  // Abstract Commands and populated the state directly, so lifting stale
  // scratch would clobber correct values. x31 (the GPR sweep base) was
  // captured via abstract read inside the drain, so only x1..x30 lift.
  // Shared by the exit drain and the reset-baseline capture.
  //
  // csr_swept: whether the drain's Andes+M-ext csrr+sd sweep ran. False on a
  // minimal drain (drain_counters_only never sweeps, and nothing stages the
  // CSR region at resume -- the restore sweep is off -- so its bytes are
  // meaningless and lifting them would corrupt the passthrough values).
  void lift_scratch_blocks(hybrid_state_v1& state, bool csr_swept)
  {
    const std::span<const uint8_t> ram{platform.main_memory.data.data(),
                                       platform.main_memory.data.size()};
    if ((state.flags & HYBRID_FLAG_V) != 0u)
      hybrid::read_v_from_scratch(state, ram);
    if (hybrid::gpr_scratch_fits(state.vlenb))
      hybrid::read_gpr_from_scratch(state, ram, 30);
    if ((state.flags & HYBRID_FLAG_FP) != 0u
        && hybrid::fpr_scratch_fits(state.vlenb))
      hybrid::read_fpr_from_scratch(state, ram);
    if (csr_swept
        && (state.flags & (HYBRID_FLAG_ANDES | HYBRID_FLAG_M_EXT)) != 0u
        && hybrid::csr_scratch_fits(state.vlenb))
      hybrid::read_csr_from_scratch(state, ram,
                                    hybrid::andes_caps_from_config());
  }

